      if (paused) return;
      var now = Date.now();
      remainingMs -= (now - lastTick);
      lastTick = now;

      if (remainingMs <= 0) {
        remainingMs = 0;
        updateTimerVisual();
        closePopupAndContinue();
        return;
      }

      updateTimerVisual();
    }, 100);

    updateTimerVisual();

    document.getElementById("popup-continue").addEventListener("click", function () {
      closePopupAndContinue();
    });
  });
});
</script>
