        overlay.appendChild(box);
        document.body.appendChild(overlay);

        var totalMs = 10000;
        var remainingMs = totalMs;
        var paused = false;
        var closed = false;
        var lastTick = Date.now();
        var timerCircle = document.getElementById("popup-timer-circle");
